'use strict';

// MODULES //

var tape = require( 'tape' );
var hasPromiseSupport = require( '@stdlib/assert/has-promise-support' );
var Promise = require( './../lib/main.js' );


// VARIABLES //

var opts = {
	'skip': !hasPromiseSupport()
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Promise, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function is a constructor which returns a promise', opts, function test( t ) {
	var p = new Promise( executor );
	t.strictEqual( typeof p.then, 'function', 'returns expected value' );
	t.end();

	function executor( resolve ) {
		resolve( 1 );
	}
});

tape( 'the constructor returns a promise which fulfills with a provided value', opts, function test( t ) {
	var p = new Promise( executor );
	p.then( onFulfill, onReject );

	function executor( resolve ) {
		resolve( 1 );
	}

	function onFulfill( value ) {
		t.strictEqual( value, 1, 'returns expected value' );
		t.end();
	}

	function onReject( error ) {
		t.fail( error.message );
		t.end();
	}
});
